import { index, integer, jsonb, pgTable, real, text, timestamp } from "drizzle-orm/pg-core";
import { user } from "./auth";
import { geometryColumn } from "./geo-column";

// ponytail: geometry generated by our own Valhalla (curvy), marked unverified until ridden
export const curatedRoutes = pgTable(
  "curated_routes",
  {
    id: text("id").primaryKey().$defaultFn(() => crypto.randomUUID()),
    nameEn: text("name_en").notNull(),
    nameSi: text("name_si"),
    nameTa: text("name_ta"),
    region: text("region").notNull().default("sri-lanka"),
    difficulty: text("difficulty").notNull().default("easy"),
    distanceKm: real("distance_km").notNull().default(0),
    coords: jsonb("coords").$type<[number, number][]>().notNull(),
    // 0008: LineString mirroring `coords`, backfilled once and kept in sync on write. Used for
    // near({lat,lon,km}) and alongRoute queries (feature-parity-plan §4.9).
    geom: geometryColumn("geometry(LineString,4326)")("geom"),
    verified: text("verified").notNull().default("generated"),
    // 0015 (feature-parity-plan §4.9, §5.5): ratings, submissions, discovery.
    // `slug` is nullable-unique rather than not-null: the five seeded rows
    // predate slugs, and a NOT NULL column with no default would fail the
    // backfill — routers enforce slug presence on write instead.
    slug: text("slug").unique(),
    descriptionEn: text("description_en"),
    descriptionSi: text("description_si"),
    descriptionTa: text("description_ta"),
    tags: text("tags").array(), // coast | hills | tea | ancient | wildlife
    curvature: real("curvature"), // core/curvature score, feeds curvy ranking
    surface: text("surface"),
    bestSeason: text("best_season"),
    ratingAvg: real("rating_avg").notNull().default(0),
    ratingCount: integer("rating_count").notNull().default(0),
    submittedBy: text("submitted_by").references(() => user.id, { onDelete: "set null" }),
    status: text("status").notNull().default("published"), // draft | review | published
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("curated_region_idx").on(t.region), index("curated_geom_idx").using("gist", t.geom)],
);
